@layer base {
  *, ::after, ::before, ::backdrop, ::file-selector-button { box-sizing: border-box; margin: 0px; padding: 0px; border: 0px solid; }
  html, :host { line-height: 1.5; text-size-adjust: 100%; tab-size: 4; -webkit-tap-highlight-color: transparent; }
  hr { height: 0px; color: inherit; border-top-width: 1px; }
  h1, h2, h3, h4, h5, h6 { font-size: inherit; font-weight: inherit; }
  a { color: inherit; text-decoration: inherit; }
  b, strong { font-weight: bolder; }
  code, kbd, samp, pre { font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace; font-size: 1em; }
  small { font-size: 80%; }
  table { text-indent: 0px; border-color: inherit; border-collapse: collapse; }
  img, svg, video, canvas, audio, iframe, embed, object { display: block; vertical-align: middle; }
  img, video { max-width: 100%; height: auto; }
  button, input, select, optgroup, textarea, ::file-selector-button { font: inherit; letter-spacing: inherit; color: inherit; border-radius: 0px; background-color: transparent; opacity: 1; }
  ::placeholder { opacity: 1; color: color-mix(currentcolor, transparent); }
  textarea { resize: vertical; }
  button, input:where([type="button"], [type="reset"], [type="submit"]), ::file-selector-button { appearance: button; }
  [hidden]:where(:not([hidden="until-found"])) { display: none !important; }
}
:root { --app-safe-bottom: env(safe-area-inset-bottom, 0px); }
html[data-flutter-app="1"] { --app-safe-bottom: 0px; }
@media (display-mode: standalone) {
  html:not([data-flutter-app="1"]) { --app-safe-bottom: max(env(safe-area-inset-bottom, 0px), 4px); --card-title-shrink: 1px; }
}
html { font-size: calc(16px * var(--app-font-scale, 1)); }
.app-spinner-shell { display: flex; align-items: center; justify-content: center; padding: 3rem 1rem; }
.app-spinner-shell--overlay { position: fixed; inset: 0px; padding: 0px; background-color: rgb(255, 255, 255); z-index: 1300; }
.app-spinner-shell--clear { background-color: transparent; animation: 0s linear 0.3s 1 normal both running app-spinner-late; }
@keyframes app-spinner-late { 
  0% { visibility: hidden; }
  100% { visibility: visible; }
}
.app-spinner { box-sizing: border-box; width: 54px; height: 54px; border-radius: 50%; border-width: 4px; border-style: solid; border-color: rgb(28, 64, 125) rgba(28, 64, 125, 0.14) rgba(28, 64, 125, 0.14); border-image: none; animation: 0.75s linear 0s infinite normal none running app-spinner-spin; }
@keyframes app-spinner-spin { 
  100% { transform: rotate(360deg); }
}
@keyframes app-slide-in { 
  0% { transform: translate(100%); }
  100% { transform: translate(0px); }
}
@keyframes app-slide-out { 
  0% { transform: translate(0px); }
  100% { transform: translate(-25%); }
}
.app-slide-in { animation: 0.26s ease-out 0s 1 normal none running app-slide-in; will-change: transform; }
.app-slide-out { animation: 0.26s ease-out 0s 1 normal forwards running app-slide-out; will-change: transform; }
@media (prefers-reduced-motion: reduce) {
  .app-slide-in, .app-slide-out { animation: auto ease 0s 1 normal none running none; }
}
body { margin: 0px; overflow-x: hidden; background: rgb(255, 255, 255); color: rgb(15, 23, 42); font-family: "Noto Sans KR", Pretendard, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Apple SD Gothic Neo", "Malgun Gothic", sans-serif; -webkit-font-smoothing: antialiased; }
.css-spinner-shell { min-height: 100vh; width: 100%; display: flex; align-items: center; justify-content: center; background-color: rgb(255, 255, 255); }
.css-spinner { box-sizing: border-box; width: 54px; height: 54px; border-radius: 50%; border-width: 4px; border-style: solid; border-color: rgb(28, 64, 125) rgba(28, 64, 125, 0.14) rgba(28, 64, 125, 0.14); border-image: none; animation: 0.75s linear 0s infinite normal none running css-spinner-spin; }
@keyframes css-spinner-spin { 
  100% { transform: rotate(360deg); }
}
.animate-cta-blink { animation: 1.6s ease-in-out 0s infinite normal none running cta-blink; }
@keyframes cta-blink { 
  0%, 100% { opacity: 1; }
  50% { opacity: 0.45; }
}
@media (prefers-reduced-motion: reduce) {
  .animate-cta-blink { animation: auto ease 0s 1 normal none running none; }
}
